    #     c5c: bhi  c7c                      ; r0 > 7 -> the default arm; `kernel_bootstrap` passes 0
    #     c60: ...  two switch tables indexed by r0
    #     c7c: movw r1, #0x2000 / movw r0, #0x201 / movt r1, #0x844
    #     c88: str  r1, [bsd_pageable_map_size]
    #     c94: str  r0, [bsd_simul_execs]
