    IOKIT_KERNEL_IOSTARTIOKIT_OBJ=${STAGE90_ENTRY_IOKIT_KERNEL_IOSTARTIOKIT_OBJ:-$REPO_ROOT/out/xnu_kernel_obj/iokit_Kernel_IOStartIOKit.o}
