    #   arm_vm_init.c:406   segTEXTB = (vm_offset_t) getsegdatafromheader(&_mh_execute_header, "__TEXT",
    #                                                                     &segSizeTEXT);
    #   arm_vm_init.c:496   vm_kernel_stext = segTEXTB;
